  rw_cells usegs m (P + 464) (ErrCodeCells EC_clear) ->
  stk usegs m lo P -> 0xb8000 <= lo -> lo + 64 <= P -> P + 488 <= 2^64 -> mem_inv usegs m ->
  evt usegs (fun ms' => exists m',
