        /\ rw_cells usegs m' (P + -64) (map C8 [s6; s5; s4; s3; s2; wz D; wz N; ra])
        /\ rw_cells usegs m' P (ParserCoreCells c pad7 pad2)
        /\ rw_cells usegs m' (P + 464) (ErrCodeCells EC_clear))
    (MS (mkR ra (Z_to_bv 64 P) gp tp t0 t1 t2 (wz N) (wz D) (wz (P + 360)) (wz (P + 416)) (wz P) (wz (P + 464)) a4 a5 a6 a7
