(* [comment removed for export] *)
Lemma RWp_init : forall (C : rsc) (c0 : pcore) (S : list Z) (ns : NS) (ls : LS) (h0 : hdrv) (hb : bool) (rdi : byte) (st : PState) (errv : word)
                        (Fs : fbv) (sds : list byte),
  rs_static C ->
  pcore_ok c0 -> pc_state c0 = 0 -> pc_hlim c0 <= 8192 -> pc_skip c0 = 0 -> hdr_empty h0 ->
  zlength sds = c_N C ->
  ((c_N C = 0 /\ Fs = FB_empty) \/ (1 <= c_N C /\ Fs = mkFB (c_A C) (c_A C) (c_A C + c_N C) (c_A C + c_N C) (c_A C + c_N C)
                                    /\ (c_A C + c_N C <= c_stb C \/ c_stb C + SZ_SPCI_STATE <= c_A C))) ->
  lb_bytes (c_LBin C) + SRO_BYTES (c_N C) <= hs_LIVE_MAX H -> Z.of_nat (length (c_LBin C)) + SRO_CNT <= hs_LIVE_CNT_MAX H ->
  RWp H C (mkW (mkPST c0 S [] ns ls ∅ h0 0 [] 0 hb rdi [] st errv) [] [] FB_empty [] Fs sds 0).
Proof.
  intros C c0 S ns ls h0 hb rdi st errv Fs sds STC PCOK ST0 HL0 SK0 HE LEN STRM BY CN.
  destruct C as [P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s8w s9w s10 s11 F fc].
  unfold RWp, rs_static in *. cbn_w_all. cbn [app length].
  destruct STC as (P0 & PBB & BHI & AL16 & CEIL & IMG & LO & NR26 & (p7 & INS) & RBS & INA & TP & MB1).
  pose proof HE as (E1 & E2 & E3 & E4 & E5 & E6).
  split; [exact PCOK|].
  split; [intros e d L0; rewrite lookup_empty in L0; discriminate|].
  split; [intros x sz []|].
  split; [unfold HdrOwnP, SvOwnP; rewrite E1, E2, E3, E4; repeat split; try lia; left; lia|].
  split; [intros e d L0; rewrite lookup_empty in L0; discriminate|].
  split; [intros x sz []|].
  split; [intros e x sz _ []|].
  split; [intros _; split; [exact HE | reflexivity]|].
  split; [clear; lia|].
  split; [cbn; clear; lia|]. split; [unfold KB; cbn; clear; lia|]. split; [clear; lia|].
  split; [intros K; exfalso; clear - K ST0; lia|].
  split; [unfold hdr_disj; rewrite E2, E4; repeat split; intros K; exfalso; exact (K eq_refl)|].
  split; [intros _; exact HL0|]. split; [rewrite SK0; clear; lia|].
  split; [intros b []|]. split; [apply Permutation_refl|]. split; [left; split; reflexivity|].
  split; [intros e He; exfalso; revert He; apply not_elem_of_nil|].
  split; [intros x sz []|].
  split; [rewrite E4; intros K; exfalso; exact (K eq_refl)|]. split; [rewrite E2; intros K; exfalso; exact (K eq_refl)|].
  split; [intros K; exfalso; exact (K eq_refl)|]. split; [intros K; exfalso; exact (K eq_refl)|]. split; [intros K; exfalso; exact (K eq_refl)|].
  split; [intros K; exfalso; exact (K eq_refl)|]. split; [intros K; exfalso; exact (K eq_refl)|].
  split. { destruct STRM as [[N0 EFs] | (N1 & EFs & SD)]; [left; split; [exact N0 | exact EFs] | right]. rewrite EFs. cbn. split; [exact N1|]. split; [reflexivity|]. split; [reflexivity | exact SD]. }
  split; [unfold zlength in LEN |- *; cbn [length Z.of_nat]; clear - LEN; lia|]. split; [clear; lia|]. split; [unfold fb_cap, CAPMAX; cbn; clear - NR26; lia|].
  rewrite ST0. unfold body_res, KB, SRO_BYTES, SRO_CNT, CAPMAX in *.
  change (if 0 <=? 9 then 34 else 0) with 34. change (if 0 <=? 1 then 8 else 0) with 8. change (if 0 <=? 9 then 2 else 0) with 2.
  change (zlength (@nil byte)) with 0. change (Z.of_nat (@length mbe [])) with 0. change (Z.of_nat (@length block [])) with 0.
  change (mb_cap []) with 0. change (lb_bytes []) with 0.
  destruct PCOK as (_ & _ & _ & _ & _ & HLR & _).
  split; [clear - BY HL0 HLR LEN NR26; lia|]. split; [clear - CN HL0 HLR; lia|]. clear - LEN NR26; lia.
Qed.

