Lemma sro_finish : forall (C : rsc) (rae s2e s3e s4e s5e s6e s7 : word) (D : Z) (pad4 : list byte) (cf : config),
  rs_static C ->
  sro_ret C rae (wz (c_N C)) (wz D) s2e s3e s4e s5e s6e s7 cf ->
  sro_post H rae (c_gp C) (c_tp C) s2e s3e s4e s5e s6e s7 (c_s8 C) (c_s9 C) (c_s10 C) (c_s11 C) (c_F C) (c_fc C)
           (c_P C) (c_N C) D (c_lo C) (c_B C) (c_stb C) (c_implb C) (c_A C) (c_LBin C)
           (c_pad7 C) (c_pad2 C) pad4 (c_j13 C) (c_j32a C) (c_j8a C) (c_j32b C) (c_j8b C) (c_mb C) (c_m0 C) (c_mo0 C) cf.
Proof.
  intros C rae s2e s3e s4e s5e s6e s7 D pad4 cf STC RET.
  destruct C as [P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s8w s9w s10 s11 F fc].
  destruct cf as [ms mo]. unfold sro_ret, RWm, rs_static in *. cbn_w_all. cbn [cfg_ms cfg_model] in RET.
  destruct STC as (P0 & PBB & BHI & AL16 & CEIL & IMG & LO & NR26 & (p7 & INS) & RBS & INA & TP & MB1).
  destruct RET as (t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & m & w & E & -> & KREL & MP & RM & RP & ST & XP).
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L ns ls em h u es insz g rdi LBn st errv]. cbn_w_all.
  destruct RM as (PC & UW & RDI & J13 & J32a & J8a & J32b & J8b & HC & FTS & MV & FBU & EC & BS & SB & HP & ERR & AUX & MI).
  unfold RWp in RP. cbn_w_all.
  destruct RP as (PCOK & OWN & MOWN & HOWN & EH & ESH & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62
                  & AOWN & PERM & FOK & FRL & FRB & FRT & FRM_ & FRF & DJL & DJB & DJT & DJM & STRM & SZS & NRK & CPM & BY & CN & IZ).
  pose proof UW as (FC & HDR & USED & MB & RD & MRG & CBH & CBB & PFT & FI & XS).
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & _).
  pose proof (FlatBuf_shape _ _ _ _ _ FBU) as (FS1 & FS2 & FS3 & FS4 & FS5).
  destruct HDJ as (J1 & J2 & J3 & J4 & J5).
  unfold sro_post. cbn [cfg_ms cfg_model].
  exists t0, t1, t2, a0, a1, a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, m, st, errv,
         (mkPST c S L ns ls em h u es insz g rdi LBn st errv), LBn, PB, FBB, FB, fds, Fs, sds, nr, (N - zlength sds), E.
  cbn_w.
  split; [reflexivity|]. split; [exact KREL|]. split; [exact MP|]. split; [exact MI|]. split; [exact ST|].
  split; [rewrite TP, EA_RATP; exact ERR|]. split; [exact AUX|]. split; [exact HP|].
  split; [exact PC|]. split; [exact PCOK|]. split; [exact FC|]. split; [exact OWN|].
  split; [exact HDR|]. split; [exact HOWN|].
  split. { (* [comment removed for export] *) split; [| split].
    - intros ML. destruct (em !! hv_mp h) as [dd|] eqn:Ld; [exfalso | reflexivity].
      destruct (J2 ltac:(clear - ML; lia) (hv_mp h) ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity)); clear - ML H0; lia.
    - intros TL. destruct (em !! hv_tp h) as [dd|] eqn:Ld; [exfalso | reflexivity].
      destruct (J1 ltac:(clear - TL; lia) (hv_tp h) ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity)); clear - TL H0; lia.
    - intros ML TL. destruct (J5 ltac:(clear - ML; lia) ltac:(clear - TL; lia)); clear - ML TL H0; lia. }
  split; [exact MB|]. split; [exact MOWN|].
  split. { (* [comment removed for export] *) intros x sz IN. pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ. split; [| split].
    - destruct (em !! x) as [dd|] eqn:Ld; [exfalso | reflexivity].
      destruct (DFB x x sz ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity) IN); clear - SZ H0; lia.
    - intros ML. destruct (J4 ltac:(clear - ML; lia) x sz IN); clear - SZ ML H0; lia.
    - intros TL. destruct (J3 ltac:(clear - TL; lia) x sz IN); clear - SZ TL H0; lia. }
  split; [exact RD|]. split; [exact RDI|]. split; [exact USED|]. split; [exact MRG|]. split; [exact J13|].
  split. { apply (proj2 (rw_cells_app _ _ _ [_] [_; _])). split; [exact J32a|]. cbn [cells_size csize Nat.add].
           apply (proj2 (rw_cells_app _ _ _ [_] [_])). split; [replace (P + 256 + 32) with (P + 288) by (clear; lia); exact CBH|].
           cbn [cells_size csize Nat.add]. replace (P + 256 + 32 + 8) with (P + 296) by (clear; lia). exact J8a. }
  split. { apply (proj2 (rw_cells_app _ _ _ [_] [_; _])). split; [exact J32b|]. cbn [cells_size csize Nat.add].
           apply (proj2 (rw_cells_app _ _ _ [_] [_])). split; [replace (P + 304 + 32) with (P + 336) by (clear; lia); exact CBB|].
           cbn [cells_size csize Nat.add]. replace (P + 304 + 32 + 8) with (P + 344) by (clear; lia). exact J8b. }
  split; [exact PERM|].
  assert (INPB : forall b, In b PB -> In b (LBn ++ LBin)).
  { intros b Hb. apply in_or_app. left. eapply Permutation_in; [apply Permutation_sym; exact PERM|]. apply in_or_app. left. exact Hb. }
  split. { (* [comment removed for export] *)
    intros b Hb. destruct (AOWN b Hb) as [[KL KS] | [K | [K | K]]].
    - left. left. destruct (proj1 (LEQ _) KL) as [dd Ld]. exists dd. split; [exact Ld|].
      destruct (OWN _ _ Ld) as [pe [INe _]]. pose proof (esize_ge dd).
      destruct b as [[pb ab] nb]. cbn in KL, KS, Ld |- *.
      pose proof (same_block H HH _ _ _ pb pe ab nb (esize dd) HP (INPB _ Hb) INe ltac:(clear - KS; lia) ltac:(clear - H0; lia)) as EQ.
      injection EQ as E1 E2. exact E2.
    - left. right. left. exact K.
    - left. right. right. exact K.
    - right. exact K. }
  split. { (* [comment removed for export] *)
    intros b Hb K. apply in_app_or in Hb. destruct Hb as [Hb | Hb].
    - (* [comment removed for export] *)
      destruct FOK as [[_ ->] | (NE & pf & ->)]; [exact Hb|]. destruct Hb as [<- | []]. cbn in K.
      destruct FS5 as [K0 | (BP & _ & BCP & _)]; [exfalso; exact (NE K0)|]. unfold fb_cap in BCP.
      destruct K as [[(dd & Ld & SZ) | [(ML1 & AB & SB1) | (TL1 & AB & SB1)]] | (sz & IN & SZ)]; cbn in *.
      + destruct (DJL NE (fb_begin FB) ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity)); clear - H0 BCP; lia.
      + destruct (DJM NE ltac:(clear - ML1; lia)); clear - H0 BCP ML1 AB; lia.
      + destruct (DJT NE ltac:(clear - TL1; lia)); clear - H0 BCP TL1 AB; lia.
      + pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ'. destruct (DJB NE _ _ IN); clear - H0 BCP SZ'; lia.
    - (* [comment removed for export] *)
      assert (RC : rclient_range LBin P (blk_addr b) (blk_size b)) by (right; right; exists b; split; [exact Hb | clear; lia]).
      destruct (hh_blocks H HH _ _ _ b HP ltac:(apply in_or_app; right; exact Hb)) as (_ & _ & Q3 & _).
      destruct K as [[(dd & Ld & SZ) | [(ML1 & AB & SB1) | (TL1 & AB & SB1)]] | (sz & IN & SZ)].
      + pose proof (esize_ge dd). destruct (FRL (blk_addr b) ltac:(apply (proj2 (LEQ _)); rewrite Ld; eexists; reflexivity) _ _ RC Q3); clear - H0 H1 SZ; lia.
      + destruct (FRM_ ltac:(clear - ML1; lia) _ _ RC Q3); clear - H0 ML1 AB SB1; lia.
      + destruct (FRT ltac:(clear - TL1; lia) _ _ RC Q3); clear - H0 TL1 AB SB1; lia.
      + pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ'. pose proof (mb_block_size_range sz ltac:(clear - SZ'; lia)) as [BR _].
        destruct (FRB _ _ IN _ _ RC Q3); clear - H0 SZ SZ' BR; lia. }
  split. { destruct FOK as [[EFB ->] | (NE & pf & ->)]; [left; split; [exact EFB | reflexivity] | right]. exists pf. split; [reflexivity|].
           destruct FS5 as [K0 | (BP & _)]; [exfalso; exact (NE K0)|]. clear - BP FS2 FS3 FS4. lia. }
  split; [exact FBU|]. split; [exact EC|]. split; [exact BS|]. split; [exact SB|].
  split; [destruct STRM as [K | (N1 & SA & SE & _)]; [left; exact K | right; split; [exact N1 | split; [exact SA | exact SE]]]|].
  split; [exists g; exact HC|]. split; [exact FTS|]. split; [exact XS|]. split; [exact PFT|]. split; [exact FI|]. split; [exact MV|]. exact XP.
Qed.

